  "m_code": "def model(df: pd.DataFrame) -> Any:
    """
    Fit a count model to test whether dark-skinned players receive more red cards than light-skinned players.

    Primary model: Negative Binomial regression of redCards on dark_binary (1=Dark, 0=Light),
    with log(games) as an offset (exposure), and controlling for country-level bias measures and player covariates.
    Cluster standard errors by referee (refNum).

    Returns the fitted result object with clustered robust standard errors.
    """
    import statsmodels.api as sm
    import statsmodels.formula.api as smf
    import numpy as np

    df = df.copy()

    # Ensure required columns exist and drop rows with missing values in model columns
    model_cols = ['redCards', 'games', 'dark_binary', 'meanIAT', 'meanExp', 'age', 'height', 'weight', 'goals', 'yellowCards', 'position', 'leagueCountry', 'refNum']
    df = df.dropna(subset=['redCards', 'games', 'dark_binary'])

    # Fill missing controls with column means where appropriate (keep strict NA handling for key covariates)
    for col in ['meanIAT', 'meanExp', 'age', 'height', 'weight', 'goals', 'yellowCards']:
        if col in df.columns:
            df[col] = pd.to_numeric(df[col], errors='coerce')
            df[col] = df[col].fillna(df[col].median())

    # Convert categorical variables to category dtype for formula handling
    if 'position' in df.columns:
        df['position'] = df['position'].astype('category')
    if 'leagueCountry' in df.columns:
        df['leagueCountry'] = df['leagueCountry'].astype('category')

    # Build formula: main predictor dark_binary, controls, and categorical fixed effects for position and leagueCountry
    formula = (
        'redCards ~ dark_binary + meanIAT + meanExp + age + height + weight + goals + yellowCards'
        ' + C(position) + C(leagueCountry)'
    )

    # Offset is log(games) to model rate per game
    offset = np.log(df['games'].astype(float))

    # Fit Negative Binomial GLM
    model_glm = smf.glm(formula=formula, data=df, family=sm.families.NegativeBinomial(), offset=offset)
    result = model_glm.fit()

    # Compute clustered robust SEs at the referee level (refNum)
    # If refNum is missing or has too many unique values, fallback to default robust covariance
    try:
        clustered = result.get_robustcov_results(cov_type='cluster', groups=df['refNum'])
    except Exception:
        clustered = result.get_robustcov_results(cov_type='HC3')

    # Return the clustered result object (has .summary() for display)
    return clustered
