  "m_code": "def model(df: pd.DataFrame):\n    # Copy to avoid modifying original\n    df = df.copy()\n\n    # Select variables used in the model and drop missing values for them\n    model_cols = [\n        'redCards', 'games', 'IsDark', 'AgeYears', 'height', 'weight',\n        'goals', 'yellowCards', 'PlayerAggressionRate', 'position', 'leagueCountry',\n        'meanIAT', 'meanExp', 'refNum'\n    ]\n    df_model = df[model_cols].dropna()\n\n    # If there is little variation in redCards, GLM will still run but results may be imprecise\n    # Build the formula. Use categorical encoding for position and leagueCountry using C(...)\n    formula = (\n        'redCards ~ IsDark + AgeYears + height + weight + goals + yellowCards + '\n        'PlayerAggressionRate + C(position) + C(leagueCountry) + meanIAT + meanExp'\n    )\n\n    # Fit a Negative Binomial GLM with log(games) as an offset (exposure). This models counts per game while\n    # accounting for differing numbers of games in each dyad.\n    # Ensure offset is the natural log of games\n    offset = np.log(df_model['games'].astype(float))\n\n    # Fit the model\n    model_glm = sm.GLM.from_formula(formula,\n                                    data=df_model,\n                                    family=sm.families.NegativeBinomial(),\n                                    offset=offset)\n    fit = model_glm.fit()\n\n    # Obtain cluster-robust standard errors clustered at the referee level (refNum)\n    try:\n        fit_robust = fit.get_robustcov_results(cov_type='cluster', groups=df_model['refNum'])\n    except Exception:\n        # If clustering fails for any reason, fall back to HC1 robust SEs\n        fit_robust = fit.get_robustcov_results(cov_type='HC1')\n\n    # Return the fitted results object with robust SEs attached\n    return fit_robust\n"
